import bisect
for values in [[], [1], [1, 1, 1], [-4, -2, -2, 0, 7], list(range(1000))]:
    saved = values[:]
    for target in [-10, -4, -2, 0, 1, 2, 7, 999, 1001]:
        assert lower_bound(values, target) == bisect.bisect_left(values, target)
